// Some portions generated by Claude

// The pinned copy of the result header row (app-shell plan decision M4.1). Follow-up of the stale-spec migration
// (.agent/execplans/workbench-stale-spec-migration-20261002.md): at 390 px the copy stuck at the desktop context bar
// height and was clamped to the card width, so the result toolbar showed above it, its columns did not match the rows
// and it could not follow horizontal scrolling.

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { loadApi } = require('./query-load-more-harness.js');

const STYLES = path.resolve(__dirname, '../../tools/workbench/src/main/webapp/styles');

function memoryStore() {
    let rows = [];
    return {
        async append(batch) { rows.push(...batch); return rows.length; },
        async read(start, count) { return rows.slice(start, start + count); },
        async count() { return rows.length; },
        async dispose() { rows = []; }
    };
}

test('the pinned header copy is exactly as wide as the table it copies', async () => {
    const { api, document, window } = loadApi();
    // Rows scroll with the page only when the page can be scrolled.
    Object.assign(window, { innerHeight: 900, scrollX: 0, scrollY: 0, scrollBy() {}, scrollTo() {} });
    const target = document.createElement('section');
    document.body.appendChild(target);
    const renderer = new api.QueryResultRenderer(target, { rowStore: memoryStore(), initialLayout: 'table' });
    await renderer.accept({ type: 'view', id: 'query-result-tuple' });
    await renderer.accept({ type: 'vars', values: ['value'] });
    await renderer.accept({ type: 'rows', values: Array.from({ length: 200 }, (_unused, index) => [
        { kind: 'literal', value: 'v' + index }
    ]) });
    await renderer.accept({ type: 'end', metadata: {} });
    await new Promise(resolve => setImmediate(resolve));
    assert.equal(renderer.root.getAttribute('data-scroll-source'), 'page');

    // The page has scrolled the table's own header row out of view, and the table is wider than the card.
    const head = renderer.table.querySelector('thead');
    head.getBoundingClientRect = () => ({ top: -100, bottom: -64, height: 36 });
    for (const original of [head, renderer.tableColumns]) {
        original.cloneNode = () => document.createElement(original.tagName);
    }
    renderer.table.getBoundingClientRect = () => ({ top: -100, bottom: 4000, left: 29, width: 791, height: 4100 });
    renderer.updateFloatingHead();

    assert.equal(renderer.floatingHead.hidden, false, 'the pinned header shows once the header row is out of view');
    const style = renderer.floatingTable.style;
    assert.deepEqual({ width: style.width, minWidth: style.minWidth, maxWidth: style.maxWidth },
        { width: '791px', minWidth: '791px', maxWidth: 'none' },
        'no inherited minimum or maximum width may resize the copy away from the table');
    renderer.dispose();
});

// The copy sticks at --workbench-contextbar-height and the renderer reads the same token for the point where it shows
// the copy, so the token has to follow the context bar into the narrow layout.
test('the narrow context bar takes its height from the token the pinned header copy sticks at', () => {
    const css = fs.readFileSync(path.join(STYLES, 'workbench-refresh.css'), 'utf8');
    const narrowBlocks = [...css.matchAll(/@media \(max-width: 900px\) \{([\s\S]*?)\n\}/g)].map(match => match[1]);
    assert.ok(narrowBlocks.some(block => /:root\s*\{\s*--workbench-contextbar-height:\s*52px;\s*\}/.test(block)),
        'the narrow layout sets the context bar height through --workbench-contextbar-height');
    assert.doesNotMatch(css, /#workbench-contextbar\.workbench-contextbar\s*\{[^}]*[\s;]height:\s*\d/,
        'no context bar rule sets a height other than the token');
});

// Narrow pages turn data tables into horizontal scroll boxes (display: block); the copy has to stay a table so that its
// columns take the widths of the copied colgroup and its viewport can scroll it.
test('the pinned header copy keeps table layout on narrow pages', () => {
    const css = fs.readFileSync(path.join(STYLES, 'query.css'), 'utf8');
    const rule = [...css.matchAll(/@media \(max-width: 900px\) \{\s*([^{}]+)\{([^}]*)\}/g)]
        .find(match => match[1].includes('.query-result-floating-head') && match[1].includes('table.data'));
    assert.ok(rule, 'the narrow layout has a table rule that covers the pinned header copy');
    assert.match(rule[2], /display:\s*table;/);
    assert.match(rule[2], /overflow:\s*visible;/);
});
